#include<stdio.h>
#include<string.h>
int	main()
{
	char s[50] = "QQqqQQwwWeeEeeERRrrrrqqtYYyyYUIOP";
	int	k = 4, chk[27] = { 0 }, b = 0;
	for (int i = 0; s[i] != 0; i++) {
		if (s[i] <= 'Z') s[i] += 32;
	}

	char a = s[0];
	int	c = 1;
	for (int i = 1; s[i] != 0; i++) {
		if (s[i] == a) {
			c++;
		}
		else {
			if (chk[a - 'a'] == 0) {
				if (c >= k)	b++;
				chk[a - 'a'] = 1;
				a = s[i];
				c = 1;
			}
			else {
				a = s[i];
				c = 1;
			}
		}
	}
	if (chk[a - 'a'] == 0 && c >= k) {
		b++;
	}
	printf("%d", b);
	return	0;
}

